(function(root){
 'use strict';
 const nutrients=['kcal','protein','carbs','fat','fiber','sodium'];
 function validEndpoint(value){try{const u=new URL(value);return (u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))&&!u.username&&!u.password&&!u.search&&!u.hash&&u.pathname==='/api/analyze-food';}catch{return false;}}
 function reviewDraft(a,details){
  if(!a||a.isFood!==true||typeof a.foodName!=='string'||!a.foodName.trim()||a.foodName.length>200||typeof a.portion!=='string'||a.portion.length>200||typeof a.note!=='string'||a.note.length>1200||!['low','medium','high'].includes(a.confidence)||!nutrients.every(k=>a[k]===null||(typeof a[k]==='number'&&Number.isFinite(a[k])&&a[k]>=0&&a[k]<=100000)))throw Error('ค่าผลวิเคราะห์ไม่ถูกต้อง ยังไม่ได้บันทึกอาหาร');
  return {name:a.foodName,...Object.fromEntries(nutrients.map(k=>[k,a[k]===null?null:Math.round(a[k]*10)/10])),meal:details.meal,time:details.time,portion:details.portion||a.portion,source:'photo-ai',estimated:true,note:'AI วิเคราะห์จากรูป · ประมาณการจากข้อมูลที่กรอก · ความมั่นใจในการระบุอาหาร/ปริมาณ: '+({low:'ต่ำ',medium:'ปานกลาง',high:'สูง'}[a.confidence])+' · '+a.note};
 }
 const api={validEndpoint,reviewDraft};
 if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}
 root.JaiFood=api;
 const $=s=>document.querySelector(s),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const CONFIG_KEY='your-day.food-endpoint.v1';let endpoint='',accessCode='',active=null,review,focusReturn;
 try{const value=localStorage.getItem(CONFIG_KEY);if(value&&validEndpoint(value))endpoint=value;}catch{}
 api.settingsHTML=()=>`<section class="card food-settings"><h2>วิเคราะห์รูปอาหารด้วย AI</h2><p class="small muted">${endpoint?'ตั้งค่าที่อยู่บริการแล้ว · ต้องมีรหัสเข้าใช้ในรอบนี้':'ยังไม่ได้เชื่อมบริการ AI · บันทึกอาหารเองได้ตามเดิม'}</p><p class="small">เปิดใช้ตาม <a href="https://github.com/mahawongsupawit125-coder/daily-routine/blob/main/FOOD-AI-SETUP.md" target="_blank" rel="noopener noreferrer">คู่มือเชื่อม AI</a></p><form id="foodApiForm"><label class="field"><span>ที่อยู่บริการวิเคราะห์อาหาร</span><input name="foodEndpoint" type="url" maxlength="500" placeholder="https://your-worker.workers.dev/api/analyze-food" value="${e(endpoint)}"><small>ใช้ HTTPS สำหรับเว็บออนไลน์ · เว้นว่างเพื่อปิดการเชื่อมต่อ</small></label><label class="field"><span>รหัสเข้าใช้บริการของคุณ</span><input name="foodAccessCode" type="password" maxlength="512" autocomplete="off" placeholder="${accessCode?'ใส่ใหม่เพื่อเปลี่ยนรหัสในรอบนี้':'รหัสที่ตั้งเป็น FOOD_ACCESS_TOKEN'}"><small>เป็นรหัสส่วนตัวที่ตั้งให้บริการของคุณ ไม่ใช่ API key ของ OpenAI · เก็บในความจำจนรีโหลดหรือปิดหน้านี้</small></label><p id="foodApiStatus" role="status" class="small"></p><div class="actions"><button class="btn primary" type="submit">บันทึกการเชื่อม AI</button><button class="btn soft" type="button" data-food-action="disconnect">ลืมรหัสในรอบนี้</button></div></form></section>`;
 api.launchHTML=()=>`<section class="card food-launch"><div><p class="eyebrow">PHOTO FOOD JOURNAL</p><h2>ถ่ายรูป แล้วบันทึกมื้อของคุณ</h2><p class="small muted">วิเคราะห์พลังงานและสารอาหารโดยประมาณ ตรวจแก้ก่อนบันทึก พร้อมระบุมื้อและเวลาที่กินจริง</p><p class="small">${endpoint?'ตั้งค่าบริการแล้ว':'ยังไม่เชื่อม AI · ถ่าย/เลือกรูปและกรอกข้อมูลเองได้'}</p></div><button class="btn primary" data-food-action="open">ถ่ายรูป / เลือกรูปอาหาร</button></section>`;
 function cancel(){if(active){active.controller?.abort();active.cancelled=true;if(active.preview)URL.revokeObjectURL(active.preview);active=null;}if($('#foodPhotoDialog')?.open)$('#foodPhotoDialog').close();focusReturn?.focus();}
 function status(message,error=false){const el=$('#foodPhotoStatus');el.textContent=message;el.classList.toggle('error',error);}
 function busy(on){const form=$('#foodPhotoForm');form.setAttribute('aria-busy',String(on));for(const x of form.querySelectorAll('input,select,button[data-food-action="analyze"],button[data-food-action="manual"]'))x.disabled=on;$('#foodAnalyze').textContent=on?'กำลังวิเคราะห์…':'วิเคราะห์รูป';}
 function open(context){
  focusReturn=document.activeElement;active={date:context.date,cancelled:false,image:null,preview:null,controller:null};
  const time=new Date().toTimeString().slice(0,5);
  $('#foodPhotoBody').innerHTML=`<p class="small muted">1. เลือกรูป → 2. วิเคราะห์ → 3. ตรวจแก้และบันทึก</p><div class="actions photo-pickers"><label class="btn primary" for="foodCamera">ถ่ายรูปอาหาร</label><input class="photo-file" id="foodCamera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"><label class="btn soft" for="foodFile">เลือกรูปจากเครื่อง</label><input class="photo-file" id="foodFile" type="file" accept="image/jpeg,image/png,image/webp"></div><img id="foodPreview" class="food-preview" alt="รูปอาหารที่เลือก" hidden><p class="small muted">JPEG / PNG / WebP ไม่เกิน 20 MB · รูปใช้วิเคราะห์ครั้งนี้ บันทึกเฉพาะผลและเวลา ไม่เก็บรูปถาวร</p><div class="form-grid"><label class="field"><span>วันที่กิน</span><input id="foodDate" type="date" min="2000-01-01" max="2100-12-31" value="${context.date}" required></label><label class="field"><span>เวลาที่กิน (แก้ไขได้)</span><input id="foodTime" type="time" value="${time}"></label></div><label class="field"><span>มื้อที่กิน</span><select id="foodMeal"><option>เช้า</option><option>กลางวัน</option><option>เย็น</option><option>ของว่าง</option><option>ไม่ระบุ</option></select></label><label class="field"><span>ปริมาณที่กินจริง</span><input id="foodPortion" maxlength="200" placeholder="เช่น ครึ่งจาน / ข้าว 1 ทัพพี + ไก่ 1 ชิ้น"></label><label class="field"><span>ชื่ออาหารหรือรายละเอียดเพิ่มเติม (ถ้าทราบ)</span><input id="foodDescription" maxlength="500" placeholder="เช่น ข้าวผัด ไม่กินน้ำจิ้ม"></label><div class="notice"><div>รูปบอกปริมาณ น้ำมัน และส่วนผสมได้ไม่ครบ ผลจึงเป็นประมาณการ · เลือกเวลาที่กินจริงก่อนบันทึก</div></div><p class="small" id="foodDestination">${endpoint?'เมื่อกดวิเคราะห์ รูปและรายละเอียดอาหารจะส่งไปที่ '+e(new URL(endpoint).origin)+' และ OpenAI':'ยังไม่เชื่อม AI ไปที่ตั้งค่า → วิเคราะห์รูปอาหารด้วย AI เพื่อเปิดใช้'}</p><label class="check-field"><input id="foodConsent" type="checkbox">ฉันยินยอมส่งรูปและรายละเอียดนี้ไปวิเคราะห์ด้วย AI</label>`;
  $('#foodMeal').value='ไม่ระบุ';$('#foodAnalyze').disabled=!endpoint;status(endpoint?(accessCode?'เลือกรูปและตรวจรายละเอียดก่อนวิเคราะห์':'กรุณาใส่รหัสเข้าใช้ AI ในตั้งค่าก่อนวิเคราะห์'):'ยังไม่เชื่อมบริการ AI · ใช้ปุ่มกรอกเองได้');$('#foodPhotoDialog').showModal();
 }
 function details(){const date=$('#foodDate').value,time=$('#foodTime').value;if(!root.Jai.validDate(date)||date<'2000-01-01'||date>'2100-12-31')throw Error('เลือกวันที่ระหว่างปี 2000–2100');return {date,time,meal:$('#foodMeal').value,portion:$('#foodPortion').value.trim(),description:$('#foodDescription').value.trim()};}
 async function compress(file,job){
  if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('เลือกรูป JPEG, PNG หรือ WebP · หากเป็น HEIC ให้แปลงหรือเลือก JPEG ก่อน');
  if(file.size>20000000)throw Error('รูปใหญ่กว่า 20 MB กรุณาย่อรูปก่อน');
  const url=URL.createObjectURL(file),img=new Image();
  try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{img.src='';reject(Error('อ่านรูปนานเกินไป กรุณาเลือกรูปใหม่'));},15000);img.onload=()=>{clearTimeout(timer);resolve();};img.onerror=()=>{clearTimeout(timer);reject(Error('อ่านรูปไม่ได้ กรุณาเลือกใหม่'));};img.src=url;});
   if(job!==active||job.cancelled)return;if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>60000000)throw Error('ขนาดรูปสูงเกินไป กรุณาย่อรูปก่อน');
   const scale=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.8);if(data.length>1800000)throw Error('รูปยังใหญ่เกินไป กรุณาเลือกรูปที่เล็กลง');return data;
  }finally{URL.revokeObjectURL(url);}
 }
 async function selectFile(file){
  const job=active;if(!job)return;job.image=null;const version=(job.version||0)+1;job.version=version;$('#foodPreview').hidden=true;status('กำลังเตรียมรูป…');
  try{const data=await compress(file,job);if(active!==job||job.version!==version||!data)return;job.image=data;$('#foodPreview').src=data;$('#foodPreview').hidden=false;status('รูปพร้อมแล้ว · ตรวจปริมาณและเวลาที่กินก่อนวิเคราะห์');}catch(err){if(active===job&&job.version===version)status(err.message,true);}
 }
 async function analyze(){
  const job=active;if(!job||job.controller)return;try{
   const info=details();if(!job.image)throw Error('ถ่ายหรือเลือกรูปอาหารก่อน');if(!endpoint)throw Error('ยังไม่เชื่อม AI กรุณาเปิดใช้ตามคู่มือในตั้งค่า');if(!accessCode)throw Error('กรุณาใส่รหัสเข้าใช้บริการ AI ในตั้งค่า');if(!$('#foodConsent').checked)throw Error('ยืนยันการส่งรูปและรายละเอียดก่อนวิเคราะห์');
   job.controller=new AbortController();busy(true);status('กำลังส่งรูปและวิเคราะห์… คุณยกเลิกได้');const timer=setTimeout(()=>job.controller?.abort(),50000);
   try{const response=await fetch(endpoint,{method:'POST',credentials:'omit',referrerPolicy:'no-referrer',headers:{'Content-Type':'application/json',Authorization:'Bearer '+accessCode},body:JSON.stringify({image:job.image,portion:info.portion,description:info.description}),signal:job.controller.signal});
    if(active!==job||job.cancelled)return;let result;try{result=await response.json();}catch{throw Error('บริการไม่ตอบข้อมูลที่ใช้ได้ ตรวจที่อยู่บริการในตั้งค่า');}if(active!==job||job.cancelled)return;if(!response.ok)throw Error(typeof result.error==='string'?result.error.slice(0,300):'วิเคราะห์ไม่สำเร็จ กรุณาลองใหม่');
    const draft=reviewDraft(result.analysis,info);cancel();review(draft,info.date);
   }finally{clearTimeout(timer);}
  }catch(err){if(active===job&&!job.cancelled)status(err.name==='AbortError'?'วิเคราะห์นานเกินไป กรุณาลองใหม่หรือกรอกเอง':err.message,true);}finally{if(active===job){job.controller=null;busy(false);}}
 }
 api.init=({onReview,getDate,openSettings})=>{
  review=onReview;const dialog=document.createElement('dialog');dialog.id='foodPhotoDialog';dialog.setAttribute('aria-labelledby','foodPhotoTitle');dialog.innerHTML='<form id="foodPhotoForm"><div class="dialog-head"><h2 id="foodPhotoTitle">บันทึกอาหารจากรูป</h2><button type="button" class="icon-btn" data-food-action="cancel" aria-label="ปิดหน้าต่างรูปอาหาร">×</button></div><div id="foodPhotoBody"></div><p id="foodPhotoStatus" role="status" class="small"></p><div class="dialog-actions"><button type="button" class="btn soft" data-food-action="settings">ตั้งค่า AI</button><button type="button" class="btn soft" data-food-action="manual">กรอกข้อมูลเอง</button><button type="button" id="foodAnalyze" class="btn primary" data-food-action="analyze">วิเคราะห์รูป</button><button type="button" class="btn soft" data-food-action="cancel">ยกเลิก</button></div></form>';document.body.append(dialog);
  dialog.addEventListener('cancel',ev=>{ev.preventDefault();cancel();});$('#foodPhotoForm').addEventListener('submit',ev=>ev.preventDefault());
  document.addEventListener('change',ev=>{if(['foodFile','foodCamera'].includes(ev.target.id)){const file=ev.target.files?.[0];if(file)selectFile(file);ev.target.value='';}});
  document.addEventListener('click',ev=>{const el=ev.target.closest('[data-food-action]');if(!el)return;const action=el.dataset.foodAction;
   if(action==='open')open({date:getDate()});if(action==='cancel')cancel();if(action==='analyze')analyze();if(action==='settings'){cancel();openSettings();}
   if(action==='manual'){try{const info=details();cancel();review({name:info.description.slice(0,200),meal:info.meal,time:info.time,portion:info.portion,source:'manual',estimated:true,note:''},info.date);}catch(err){status(err.message,true);}}
   if(action==='disconnect'){accessCode='';$('#foodApiStatus').textContent='ลืมรหัสแล้ว · ใส่ใหม่เมื่อต้องการวิเคราะห์';}
  });
  document.addEventListener('submit',ev=>{if(ev.target.id!=='foodApiForm')return;ev.preventDefault();const form=ev.target,newEndpoint=form.elements.foodEndpoint.value.trim(),code=form.elements.foodAccessCode.value.trim();try{
   if(newEndpoint&&!validEndpoint(newEndpoint))throw Error('ใช้ HTTPS และลงท้าย /api/analyze-food โดยไม่มีรหัสหรือพารามิเตอร์ใน URL');if(code.startsWith('sk-'))throw Error('ช่องนี้ใช้รหัส FOOD_ACCESS_TOKEN ของคุณ ไม่ใช้ API key ของ OpenAI');if(code&&code.length<32)throw Error('รหัสเข้าใช้ต้องมีอย่างน้อย 32 ตัวอักษร');
   if(newEndpoint)localStorage.setItem(CONFIG_KEY,newEndpoint);else localStorage.removeItem(CONFIG_KEY);if(endpoint!==newEndpoint)accessCode='';endpoint=newEndpoint;accessCode=endpoint?(code||accessCode):'';form.elements.foodAccessCode.value='';$('#foodApiStatus').textContent=endpoint?'บันทึกที่อยู่แล้ว · '+(accessCode?'รหัสพร้อมใช้จนกว่าจะรีโหลดหน้านี้':'กรุณาใส่รหัสเพื่อวิเคราะห์'):'ปิดการเชื่อม AI แล้ว';
  }catch(err){$('#foodApiStatus').textContent=err.message;}});
 };
})(globalThis);
